//@ts-nocheck
import { Component, Element, Host, Prop, h } from "@stencil/core";
import * as d3 from "d3";
import merge from "deepmerge";

import {
  computeArcEndAngle,
  computeArcInnerRadius,
  computeArcOutterRadius,
  computeArcStartAngle,
  computeNodeRotation,
  // getTransformation,
  iteratorToAlphabet,
} from "./helper";

interface TreeNode {
  children?: TreeNode[];
  name: string; // label text on circle sector or leaf
  backgroundColor?: string; // background color for circle sector or leaf
  strokeColor?: string; // border/stroke color for circle sector or leaf
  tooltip?: {
    // tooltip for leaf
    slot?: HTMLElement; // slot or text, slot div must be defined with as <div></div> per tooltip spec
    text?: string;
    distance: number;
    containerStyle: string; // css of the tooltip, width is 100px by default and can be overrided since it is in a foreignObject in an SVG
    placement: string;
  };
  leaf?: {
    label?: {
      paddingX?: number;
      paddingY?: number;
      borderRadius?: number;
      backgroundColor?: string;
      fontSize?: number;
      lineHeight?: number;
      deltaX?: number;
      deltaY?: number;
    };
    line?: {
      color?: string;
      startPercent: number; // where polyline coming from the circle sector
      endPercent: number; // where polyline going to the label
    };
    dot: {
      size?: number;
      color?: string;
      strokeColor?: string;
      strokeWidth?: number;
    };
  };
  event?: {
    // event for leaf
    click?: (d: Record<string, string>, event: Event) => void; // param1 = target item, param2 = event
    mouseenter?: (d: Record<string, string>, event: Event) => void; // param1 = target item, param2 = event
    mouseover?: (d: Record<string, string>, event: Event) => void; // param1 = target item, param2 = event
    mouseout?: (d: Record<string, string>, event: Event) => void; // param1 = target item, param2 = event
  };
}

const POPOVER_DISTANCE = 10;
const POPOVER_PLACEMENT = "top";
const POPOVER_STYLE_APPLY_DELAY = 10;
const CENTER_TEXT_FACTOR = 3.5;
const LINE_START_PERCENT = 1;
const LINE_END_PERCENT = 1;
const LEAF_EXPAND_FACTOR = 1.1;
const LEAF_EXPAND_DELTA_X = 180;
const LEAF_EXPAND_DELTA_Y = 0;

let maxDepth = 0;

@Component({
  tag: "hbr-explore",
  styleUrl: "explore.scss",
  shadow: true,
})
export class HbrExploreChart {
  @Element() host: HTMLHbrExploreElement;
  tooltipRef: HTMLHbrPopoverElement;
  chartRef: HTMLElement;
  boardRef: HTMLHbrChartBoardElement;

  @Prop() loading = false;

  /** config set the data, width and height of the canvas, scale is to set the size of the chart */
  @Prop() config: {
    data: TreeNode /** tree object for explore data */;
    width?: number;
    height?: number;
    scale?: number;
    sector?: {
      heightDiff?: number;
      fontSize?: number;
      textUpperDelta1?: number;
      textLowerDelta1?: number;
      textUpperDelta2?: number;
      textLowerDelta2?: number;
      textUpperDelta3?: number;
      textLowerDelta3?: number;
    };
    midSector?: {
      fontSize?: string;
      padding?: string;
      width?: string;
      height?: string;
    };
    // global setting for treeNode
    leaf: {
      label?: {
        paddingX?: number;
        paddingY?: number;
        borderRadius?: number;
        backgroundColor?: string;
        fontSize?: number;
        lineHeight?: number;
        deltaX?: number;
        deltaY?: number;
      };
      line?: {
        color?: string;
        startPercent?: number;
        endPercent?: number;
      };
      dot?: {
        size?: number;
        color?: string;
        strokeColor?: string;
        strokeWidth?: number;
      };
    };
  } = {
    data: {
      name: "Empty Root",
    },
    leaf: {
      label: {
        paddingX: 20,
        paddingY: 10,
        borderRadius: 10,
        backgroundColor: "transparent",
        deltaX: 180,
        deltaY: 0,
      },
    },
    width: 720,
    height: 480,
    scale: 0.85,
    sector: {
      fontSize: 18,
      heightDiff: 0,
      textUpperDelta1: 32,
      textLowerDelta1: -18,
      textUpperDelta2: 32,
      textLowerDelta2: -18,
      textUpperDelta3: 32,
      textLowerDelta3: -18,
    },
  };

  async componentDidLoad() {
    await this.boardRef.setChartConfig(this.config);
    setTimeout(() => {
      this.renderChart();
    }, 50);
  }

  async componentShouldUpdate() {
    await this.boardRef.setChartConfig(this.config);
    setTimeout(() => {
      this.renderChart();
    }, 50);
  }

  addingStylesToTree = (obj, walker, config) => {
    if (obj.children) {
      if (obj.depth === 0) {
        obj.children = obj.children.map((r, i) =>
          this.addingStylesToTree(r, i, config)
        );
      } else {
        obj.children = obj.children.map((r) =>
          this.addingStylesToTree(r, walker, config)
        );
      }
    }

    obj.data = {
      ...obj.data,
      backgroundColor:
        obj.data.backgroundColor ||
        (obj.depth === 0
          ? "var(--info-bg-medium-default)"
          : `var(--accent-${iteratorToAlphabet(walker)}-default)`),
      leaf: {
        ...obj.data.leaf,
        label: {
          paddingX:
            obj.data.leaf?.label?.paddingX || config.leaf?.label?.paddingX,
          paddingY:
            obj.data.leaf?.label?.paddingY || config.leaf?.label?.paddingY,
          borderRadius:
            obj.data.leaf?.label?.borderRadius ||
            config.leaf?.label?.borderRadius,
          backgroundColor:
            obj.data.leaf?.label?.backgroundColor ||
            config.leaf?.label?.backgroundColor,
          fontSize:
            obj.data.leaf?.label?.fontSize || config.leaf?.label?.fontSize,
          lineHeight:
            obj.data.leaf?.label?.lineHeight || config.leaf?.label?.lineHeight,
          deltaX: obj.data.leaf?.label?.deltaX || config.leaf?.label?.deltaX,
          deltaY: obj.data.leaf?.label?.deltaY || config.leaf?.label?.deltaY,
        },
        line: {
          color: obj.data.leaf?.line?.color || config.leaf?.line?.color,
          startPercent:
            obj.data.leaf?.line?.startPercent ||
            config.leaf?.line?.startPercent,
          endPercent:
            obj.data.leaf?.line?.endPercent || config.leaf?.line?.endPercent,
        },
        dot: {
          size: obj.data.leaf?.dot?.size || config.leaf?.dot?.size,
          color: obj.data.leaf?.dot?.color || config.leaf?.dot?.color,
          strokeColor:
            obj.data.leaf?.dot?.strokeColor || config.leaf?.dot?.strokeColor,
          strokeWidth:
            obj.data.leaf?.dot?.strokeWidth || config.leaf?.dot?.strokeWidth,
        },
      },
    };
    obj.data.children = undefined;
    return obj;
  };

  renderChart = () => {
    const { addingStylesToTree, chartRef, tooltipRef, config } = this;

    // deep merge
    const chartConfig = merge(
      {
        data: {
          name: "Empty Root",
        },
        width: 720,
        height: 480,
        scale: 0.85,
        sector: {
          heightDiff: 0,
          fontSize: 18,
          textUpperDelta1: 32,
          textLowerDelta1: -18,
          textUpperDelta2: 32,
          textLowerDelta2: -18,
          textUpperDelta3: 32,
          textLowerDelta3: -18,
        },
        leaf: {
          label: {
            paddingX: 20,
            paddingY: 10,
            borderRadius: 10,
            backgroundColor: "transparent",
          },
        },
      },
      config
    );

    if (chartRef.innerHTML.length) {
      // remove all content in the ref before creating chart
      chartRef.innerHTML = "";
    }

    const width = chartConfig.width;
    const height = chartConfig.height;
    const radius = Math.min(width, height) / 2;

    const svg = d3
      .select(chartRef)
      .append("svg")
      .attr("width", width)
      .attr("height", height)
      .append("g")
      .attr(
        "transform",
        `translate(${width / 2},${height / 2}) rotate(-90 0 0) scale(${
          chartConfig.scale
        })`
      );

    const partition = d3.partition().size([360, radius]).padding(0);

    // set equal size of each circle section
    const root = d3
      .hierarchy(config.data, (d) => d.children)
      .sum((d) => {
        if (d.children) {
          return 0;
        }
        return 1;
      });

    let chartPartition = partition(root);

    // coloring
    chartPartition = addingStylesToTree(chartPartition, 0, chartConfig);

    const leaves = chartPartition.leaves();
    const branch = chartPartition.descendants().filter((r) => r.children);

    // setting max depth for polyline to inject proper width
    // based on relative depth later
    leaves.forEach((d) => {
      if (d.depth > maxDepth) {
        maxDepth = d.depth;
      }
    });

    const centerArc = d3
      .arc()
      .startAngle((d) => {
        return computeArcStartAngle(d);
      })
      .endAngle((d) => {
        return computeArcEndAngle(d);
      })
      .innerRadius((d) => computeArcInnerRadius(d, radius))
      .outerRadius((d) => {
        if (d.depth === maxDepth - 1) {
          return (
            computeArcOutterRadius(d, radius) - chartConfig.sector.heightDiff
          );
        }
        return computeArcOutterRadius(d, radius);
      });

    const polylineContainer = svg.append("g");

    // creating circle section with color
    svg
      .selectAll("path")
      .data(branch)
      .enter()
      .append("path")
      .attr("d", centerArc)
      .attr("fill-rule", "evenodd")
      .style(
        "stroke",
        (d) => d.data.strokeColor || "var(--base-bg-weak-default)"
      )
      .style("fill", (d) => d.data.backgroundColor);

    // add special case for root element
    const g = svg
      .selectAll("g")
      .filter((group) => group === polylineContainer)
      .data(branch)
      .enter()
      .append("g")
      .each(function (d) {
        if (d.depth === 0) {
          d3.select(this).attr("transform", "rotate(90 0 0)");
        }
      });

    g.append("path")
      .attr("d", centerArc)
      // .attr("stroke", "var(--background-secondary, #F5F6F7)")
      // .attr("stroke-width", "3px")
      // .attr("id", d => "dna-expore-outter-path-id-" + d.data.name)
      .style("fill", "none")
      .each(function (z) {
        // Search pattern for everything between the start and the first capital L
        const firstArcSection = /(^.+?)L/;

        // Grab everything up to the first Line statement
        let pathToFind: string = firstArcSection.exec(
          d3.select(this).attr("d")
        ) as unknown as string;

        if (pathToFind?.[1]) {
          pathToFind = pathToFind[1];
          // Replace all the comma's so that IE can handle it
          pathToFind = (pathToFind as string).replace(/,/g, " ");
          const start = computeArcStartAngle(z);
          const end = computeArcEndAngle(z);
          const mid = Math.abs((end - start) / 2 + start);

          // if the middle text label of a section is over 180 degree
          // flip the label
          if ((mid * 180) / Math.PI >= 180) {
            const startLoc = /M(.*?)A/; //Everything between the first capital M and first capital A
            const middleLoc = /A(.*?)0 0 1/; //Everything between the first capital A and 0 0 1
            const endLoc = / 0 0 1 (.*?)$/; //Everything between the first 0 0 1 and the end of the string (denoted by $)
            //Flip the direction of the arc by switching the start en end point (and sweep flag)
            //of those elements that are below the horizontal line
            let newStart = endLoc.exec(pathToFind);
            const newEnd = startLoc.exec(pathToFind);
            let middleSec = middleLoc.exec(pathToFind);

            // Build up the new arc notation, set the sweep-flag to 0
            // some weird exception for path does not contain 001, but 011`
            // buggy
            if (!newStart) {
              newStart = / 0 1 1 (.*?)$/.exec(pathToFind);
              middleSec = /A(.*?)0 1 1/.exec(pathToFind);
              if (newStart && middleSec && newEnd) {
                pathToFind = `M${newStart[1]}A${middleSec[1]}0 1 0 ${newEnd[1]}`;
              } else {
                pathToFind = "";
              }
            } else {
              pathToFind = `M${newStart[1]}A${middleSec[1]}0 0 0 ${newEnd[1]}`;
            }
          }

          if (pathToFind.length) {
            //Create a new invisible arc that the text can flow along
            d3.select(this)
              .append("path")
              .attr("id", (d) => `harbor-explore-inner-path-id-${d.data.name}`)
              .attr("d", pathToFind)
              .style("fill", "none");
          }
        }
      });

    g.each(function (d) {
      if (d.depth === 0) {
        // this is to add center text
        const fo = d3
          .select(this)
          .append("foreignObject")
          .attr("x", -computeArcOutterRadius(d, radius))
          .attr("y", -computeArcOutterRadius(d, radius))
          .attr("width", (d) => 2 * computeArcOutterRadius(d, radius))
          .attr("height", (d) => 2 * computeArcOutterRadius(d, radius));

        fo.append("xhtml:div")
          .style(
            "width",
            chartConfig.midSector?.width
              ? `${chartConfig.midSector?.width}px`
              : "calc(100% - 1em)"
          )
          .style(
            "height",
            chartConfig.midSector?.height
              ? `${chartConfig.midSector?.width}px`
              : "calc(100% - 1em)"
          )
          .style("display", "flex")
          .style("justify-content", "center")
          .style("align-items", "center")
          .style("text-align", "center")
          .style(
            "padding",
            chartConfig.midSector?.padding
              ? `${chartConfig.midSector?.padding}px`
              : "0.5em"
          )
          .style(
            "font-size",
            chartConfig.midSector?.fontSize
              ? `${chartConfig.midSector?.fontSize}px`
              : `${
                  computeArcOutterRadius(d, radius) /
                  d.data.name.length /
                  CENTER_TEXT_FACTOR
                }em`
          )
          .text(d.data.name);
      } else {
        d3.select(this)
          .append("text")
          .attr("dy", (d) => {
            const start = computeArcStartAngle(d);
            const end = computeArcEndAngle(d);
            const mid = Math.abs((end - start) / 2 + start);

            // return (mid * 180) / Math.PI >= 180
            // ? `${-Math.pow(0.75, d.depth - 1) * 0.7}em`
            // : `${Math.pow(1, d.depth - 1) * 1.3}em`;

            // const inner = computeArcInnerRadius(d, radius);
            // const outter = computeArcOutterRadius(d, radius);

            //text placement is troublesome for circle sector
            // hard coding 1 level for now

            return (mid * 180) / Math.PI >= 180
              ? `${chartConfig.sector[`textLowerDelta${d.depth}`]}px`
              : `${chartConfig.sector[`textUpperDelta${d.depth}`]}px`;
          })
          .attr("font-size", () => `${chartConfig.sector.fontSize}px`)
          .attr(
            "font-family",
            'CiscoSans,Arial,Helvetica,"Helvetica Neue",HelveticaNeue,"Lucida Grande",sans-serif'
          )
          .append("textPath") //append a textPath to the text element
          .attr("xlink:href", (d) =>
            d.depth === 0 ? "" : `#harbor-explore-inner-path-id-${d.data.name}`
          )
          .style("text-anchor", "middle") //place the text halfway on the arc
          .attr("startOffset", "50%")
          // per Mandy
          .attr("fill", (d) => d.labelColor || "var(--info-bg-medium-active)")
          .text((d) => d.data.name);
      }
    });

    const dotContainer = svg.append("g");
    const dots = dotContainer.selectAll("g").data(leaves).enter();

    const arc = d3
      .arc()
      .startAngle((d) => computeArcStartAngle(d))
      .endAngle((d) => computeArcEndAngle(d))
      .innerRadius((d) => computeArcInnerRadius(d, radius))
      .outerRadius((d) => computeArcOutterRadius(d, radius));

    dots
      .append("circle")
      .attr(
        "cx",
        (d) => computeArcInnerRadius(d, radius) - chartConfig.sector.heightDiff
      )
      .attr("dy", 0) // vertical-align
      .attr("transform", (d) => `rotate(${computeNodeRotation(d)})`)
      .attr("r", (d) => `${d.data.leaf?.dot?.size || 10}px`)
      .style("fill", (d) => d.data.leaf?.dot?.color || d.data.backgroundColor)
      .style(
        "stroke",
        (d) => d.data.leaf?.dot?.strokeWidth || "var(--base-bg-weak-default)"
      )
      .style("stroke-width", (d) => `${d.data.leaf?.dot?.strokeWidth || 4}px`);

    const labelboxContainer = svg.append("g");

    const bars = labelboxContainer
      .selectAll("allLabels")
      .data(leaves)
      .enter()
      .append("g")
      .attr("transform", (d) => {
        const pos = arc.centroid(d);

        let translation = [0, 0];

        translation = [
          pos[0] * LEAF_EXPAND_FACTOR +
            (d.data.leaf?.label?.deltaY || LEAF_EXPAND_DELTA_Y),
          pos[1] > 0
            ? pos[1] + (d.data.leaf?.label?.deltaX || LEAF_EXPAND_DELTA_X)
            : pos[1] - (d.data.leaf?.label?.deltaX || LEAF_EXPAND_DELTA_X),
        ];

        return `translate(${translation}) rotate(90)`;
      });

    // This creates text tag as a placeholder for width of foreignObject
    // Since foreignObject width needed to be hardcoded
    bars
      .append("svg")
      .attr("dx", 0)
      .attr("dy", 0)
      .style("overflow", "auto")
      .append("text")
      .text((d) => d.data.name)
      .attr("fill", "transparent")
      .style("text-anchor", "middle")
      .style("alignment-baseline", "middle")
      .style("pointer-events", "none")
      .attr("font-size", (d) =>
        d.data.leaf.label.fontSize ? `${d.data.leaf.label.fontSize}px` : "100%"
      )
      .each(function (d) {
        const id = `hbr-explore-item-${Math.random().toString(16).slice(2)}`;
        const box = d3.select(this.parentNode).node().getBBox();
        d3.select(this.parentNode)
          .append("foreignObject")
          .attr("id", id)
          .style("color", (d) => d.data.labelColor)
          .attr("x", () => {
            return box.x - d.data.leaf.label.paddingX;
          })
          .attr("y", box.y - d.data.leaf.label.paddingY)
          .attr("width", box.width + d.data.leaf.label.paddingX * 2)
          .attr("height", box.height + d.data.leaf.label.paddingY * 2)
          .style("padding", `0 ${d.data.leaf.label.paddingX}px`)
          .style("font-size", `${d.data.leaf.label.fontSize}px`)
          .style(
            "line-height",
            d.data.leaf.label.lineHeight
              ? `${d.data.leaf.label.lineHeight}px`
              : "inherit"
          )
          .style("border-radius", `${d.data.leaf.label.borderRadius}px`)
          .style("overflow", "visible")
          .style("cursor", (d) =>
            d.data.event?.click ? "pointer" : "not-allowed"
          )
          .style("user-select", "none")
          .on("mouseenter", (z) => {
            if (d.data.event?.mouseenter) {
              d.data.event.mouseenter(d, z);
            }
          })
          .on("mouseover", (z) => {
            const { slot, text, containerStyle, placement, distance } =
              d?.data?.tooltip || {};
            if (slot || text) {
              const content = tooltipRef.querySelector(
                "[slot=content]"
              ) as HTMLDivElement;
              if (typeof distance === "number") {
                tooltipRef.distance = distance;
              }
              if (placement) {
                tooltipRef.placement = placement;
              }
              if (d?.data?.tooltip) {
                content.innerHTML = text ?? slot;
              }

              tooltipRef.anchor = `#${id}`;
              if (containerStyle) {
                // because the popover body is in a shadow dom,
                // updating above attr causes popover component update,
                // which does not wait and override styles here, a setTimeout is to wait and update
                setTimeout(() => {
                  tooltipRef.shadowRoot.querySelector(
                    ".popover__body"
                  ).style.cssText = containerStyle;

                  if (content.innerHTML.length) {
                    tooltipRef.open = true;
                  }
                }, POPOVER_STYLE_APPLY_DELAY);
              } else {
                tooltipRef.open = true;
              }
            }
            if (d.data.event?.mouseover) {
              d.data.event.mouseover(d, z);
            }
          })
          .on("mouseout", (z) => {
            if (d?.data?.tooltip?.slot || d?.data?.tooltip?.text) {
              tooltipRef.open = false;
              tooltipRef.querySelector("[slot=content]").innerHTML = "";
              tooltipRef.distance = POPOVER_DISTANCE;
              tooltipRef.placement = POPOVER_PLACEMENT;
              tooltipRef.shadowRoot.querySelector(
                ".popover__body"
              ).style.cssText = "";
            }
            if (d.data.event?.mouseout) {
              d.data.event.mouseout(d, z);
            }
          })
          .on("click", (z) => {
            if (d.data.event?.click) {
              d.data.event.click(d, z);
            }
          })
          .html((c) => {
            if (c.data?.tooltip?.text || c.data?.tooltip?.slot) {
              return `<div>${c.data.name}</div>`;
            }
            return c.data.name;
          });

        // insert rect box before text for z index purpose
        d3.select(this.parentNode)
          .insert("svg", ":first-child")
          .style("overflow", "auto")
          .style("filter", () => {
            // return 'blue'
            // if (d.state && d.state === "filled") {
            //   return "drop-shadow(0px 0px 2px var(--background-primary, #ffffff))";
            // } else if (d.state && d.state === "normal") {
            //   return "drop-shadow(0px 0px 2px var(--primary-color, #0076D5)";
            // } else if (d["link-only"]) {
            //   return "drop-shadow(0px 0px 2px var(--primary-color, #0076D5))";
            // }
          })
          .append("rect")
          .attr("x", () => box.x - d.data.leaf.label.paddingX)
          .attr("y", box.y - d.data.leaf.label.paddingY)
          .attr("rx", () => d.data.leaf.label.borderRadius)
          .attr("width", () => {
            return box.width + d.data.leaf.label.paddingX * 2;
          })
          .attr("height", box.height + d.data.leaf.label.paddingY * 2)
          .style("fill", d.data.leaf.label.backgroundColor)
          .attr("opacity", 1)
          .attr(
            "stroke",
            () => d.data.leaf?.dot?.color || d.data.backgroundColor
          );
        polylineContainer
          .append("polyline")
          .attr(
            "stroke",
            () =>
              d.data.leaf?.line?.color ||
              d.data.leaf?.dot?.color ||
              d.data.backgroundColor
          )
          .style("fill", "none")
          .attr("stroke-width", d.data.leaf?.line?.width || 1)
          .attr("points", () => {
            const pos = arc.centroid(d);
            const posA = [];
            const posB = [];

            // label is at 10% outward with LEAF_EXPAND_FACTOR value
            // and then LEAF_EXPAND_FACTOR for the next part which matches label box

            posA[0] =
              (d.data.leaf?.line.startPercent || LINE_START_PERCENT) * pos[0];
            posA[1] =
              (d.data.leaf?.line.startPercent || LINE_START_PERCENT) * pos[1];

            posB[0] = LEAF_EXPAND_FACTOR * pos[0];
            posB[1] = LEAF_EXPAND_FACTOR * pos[1];

            const posC = [
              posB[0] + (d.data.leaf?.label?.deltaY || LEAF_EXPAND_DELTA_Y),
              posB[1] > 0
                ? posB[1] +
                  (d.data.leaf?.label?.deltaX || LEAF_EXPAND_DELTA_X) *
                    (d.data.leaf?.line.endPercent || LINE_END_PERCENT)
                : posB[1] -
                  (d.data.leaf?.label?.deltaX || LEAF_EXPAND_DELTA_X) *
                    (d.data.leaf?.line.endPercent || LINE_END_PERCENT),
            ];

            return [posA, posB, posC];
          });
      });

    d3.select(self.frameElement).style("height", `${height}px`);
  };
  render() {
    return (
      <Host>
        <hbr-chart-board
          ref={(el) => {
            this.boardRef = el;
          }}
          isLoading={this.loading}
          style={{ width: "100%", height: "100%" }}
        >
          <hbr-popover
            distance={POPOVER_DISTANCE}
            anchor=""
            ref={(el) => {
              this.tooltipRef = el;
            }}
            part="popover"
            variant="chart"
            placement={POPOVER_PLACEMENT}
          >
            <div slot="content">
              <div style={{ display: "flex", justifyContent: "space-between" }}>
                <div
                  style={{ display: "flex", alignItems: "center", gap: "6px" }}
                >
                  <div
                    class="color"
                    style={{ width: "16px", height: "16px", background: "" }}
                  />
                  <span />
                </div>
                <div>
                  <span />
                </div>
              </div>
            </div>
          </hbr-popover>
          <div
            style={{ width: "100%", height: "100%" }}
            ref={(el) => {
              this.chartRef = el;
            }}
            class="--hbr-explore"
            part="chart"
          />
          <div slot="footer">
            <slot name="footer" />
          </div>
          <div slot="loading-state">
            <slot name="loading-state" />
          </div>
          <div slot="empty-state">
            <slot name="empty-state" />
          </div>
        </hbr-chart-board>
      </Host>
    );
  }
}
